<?php declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use Pruebas\Catalogo\Estado;
use gamboamartin\errores\errores;
final class CatalogoPartidaTest extends TestCase {
 protected function setUp():void {require_once __DIR__.'/soporte_catalogo.php';require_once RAIZ_REPOSITORIO_PRUEBAS.'/orm/com_producto.php';Estado::$clientes=[1=>(object)['com_tipo_cliente_id'=>1],2=>(object)['com_tipo_cliente_id'=>2]];Estado::$tipos=[];Estado::$precios=[];Estado::$calls=[];Estado::$fallo=null;Estado::$despues=null;errores::$error=false;}
 private function model():gamboamartin\facturacion\models\com_producto {return new gamboamartin\facturacion\models\com_producto(new Pruebas\Catalogo\ConexionSinRed());}
 private function products():array{return [7=>['com_producto_id'=>1,'com_producto_precio'=>'100','cat_sat_conf_imps_id'=>3,'otro'=>'intacto'],9=>['com_producto_id'=>2,'com_producto_precio'=>'50','cat_sat_conf_imps_id'=>4,'otro'=>'segundo']];}
 private function type(int $id,string $price):array{return ['com_producto_id'=>$id,'com_conf_precio_precio'=>$price,'status'=>'inactivo'];}
 private function special(int $id,string $price,int $tax=8):array{return ['com_producto_id'=>$id,'com_precio_cliente_precio'=>$price,'cat_sat_conf_imps_id'=>$tax,'status'=>'inactivo'];}
 public function testVacioNoConsultaClienteInvalido():void {self::assertSame([],$this->model()->precios_para_alta([],0));self::assertSame([],Estado::$calls);self::assertFalse(errores::$error);}
 public function testPrecioClienteSobreTipoYBase():void {Estado::$tipos[1]=[$this->type(1,'80'),$this->type(2,'40')];Estado::$precios[1]=[$this->special(1,'70')];$r=$this->model()->precios_para_alta($this->products(),1);self::assertSame(70.0,$r[7]['com_producto_precio']);self::assertSame(40.0,$r[9]['com_producto_precio']);}
 public function testFiscalSoloOverrideCliente():void {Estado::$tipos[1]=[$this->type(2,'40')];Estado::$precios[1]=[$this->special(1,'70',12)];$r=$this->model()->precios_para_alta($this->products(),1);self::assertSame(12,$r[7]['cat_sat_conf_imps_id']);self::assertSame(4,$r[9]['cat_sat_conf_imps_id']);}
 public function testOrdenIndicesYCamposSinMutarEntrada():void {$p=$this->products();$copy=$p;$r=$this->model()->precios_para_alta($p,1);self::assertSame($copy,$p);self::assertSame([7,9],array_keys($r));self::assertSame('intacto',$r[7]['otro']);self::assertSame('segundo',$r[9]['otro']);}
 public function testRedondeoFronteras():void {foreach(['1.005'=>1.01,'2.675'=>2.68,'-1.005'=>-1.01,'0.0049'=>0.0,'0.005'=>0.01,'-0.005'=>-0.01] as $input=>$expected){$p=$this->products();$p[7]['com_producto_precio']=$input;self::assertSame($expected,$this->model()->precios_para_alta($p,1)[7]['com_producto_precio']);}}
 public function testOverridesInactivosNoSeDescartan():void {Estado::$tipos[1]=[$this->type(2,'0.005')];Estado::$precios[1]=[$this->special(1,'-1.005')];$r=$this->model()->precios_para_alta($this->products(),1);self::assertSame(-1.01,$r[7]['com_producto_precio']);self::assertSame(0.01,$r[9]['com_producto_precio']);}
 public function testClientesAlternadosSinCache():void {Estado::$precios[1]=[$this->special(1,'70')];Estado::$precios[2]=[$this->special(1,'20')];$m=$this->model();foreach([1=>70.0,2=>20.0] as $c=>$v)self::assertSame($v,$m->precios_para_alta($this->products(),$c)[7]['com_producto_precio']);self::assertSame(70.0,$m->precios_para_alta($this->products(),1)[7]['com_producto_precio']);}
 public function testFiltrosConservanTipoYCliente():void {$this->model()->precios_para_alta($this->products(),2);self::assertContains(['tipo_filtro',['com_tipo_cliente.id'=>2]],Estado::$calls);self::assertContains(['precio_filtro',['com_cliente.id'=>2]],Estado::$calls);self::assertContains(['cliente_filtro',2,true,true],Estado::$calls);}
 public function testConsultasNoCrecenPorProducto():void {$m=$this->model();$p=[];for($i=1;$i<=100;$i++)$p[]=['com_producto_id'=>$i,'com_producto_precio'=>'1','cat_sat_conf_imps_id'=>1];$r=$m->precios_para_alta($p,1);self::assertCount(100,$r);self::assertSame(['cliente','tipo','precio'],array_values(array_filter(Estado::$calls,'is_string')));}
 public function testDuplicadoPrimeroDetieneAntesPrecioClienteSinReleer():void {Estado::$tipos[1]=[$this->type(1,'80'),$this->type(1,'90')];$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame('Error existe mas de un precio',$r['data']['mensaje_limpio']);self::assertNotContains('precio',Estado::$calls);self::assertSame(2,$r['data']['data']->n_registros);}
 public function testDuplicadoClienteConservaFilasObservadas():void {Estado::$precios[1]=[$this->special(2,'30'),$this->special(2,'40')];$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame(Estado::$precios[1],$r['data']['data']->registros);}
 public function testDuplicadosFueraCatalogoSeIgnoran():void {Estado::$tipos[1]=[$this->type(99,'1'),$this->type(99,'2')];Estado::$precios[1]=[$this->special(99,'1'),$this->special(99,'2')];self::assertCount(2,$this->model()->precios_para_alta($this->products(),1));self::assertFalse(errores::$error);}
 public function testFalloClienteConservaCausaYDetiene():void {Estado::$fallo='cliente';$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame('FALLO_SQL_FICTICIO_cliente',$r['data']['mensaje_limpio']);self::assertNotContains('tipo',Estado::$calls);}
 public function testFalloTipoConservaCausaYDetiene():void {Estado::$fallo='tipo';$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame('FALLO_SQL_FICTICIO_tipo',$r['data']['mensaje_limpio']);self::assertNotContains('precio',Estado::$calls);}
 public function testFalloPrecioConservaCausaSinReintentar():void {Estado::$fallo='precio';$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame('FALLO_SQL_FICTICIO_precio',$r['data']['mensaje_limpio']);self::assertSame(1,count(array_filter(Estado::$calls,fn($v)=>$v==='precio')));}
 public function testDuplicadoDesapareceDespuesLecturaSinReconsulta():void {Estado::$tipos[1]=[$this->type(1,'80'),$this->type(1,'90')];Estado::$despues=function(string $etapa):void {if($etapa==='tipo')Estado::$tipos[1]=[];};$r=$this->model()->precios_para_alta($this->products(),1);self::assertTrue(errores::$error);self::assertSame(2,$r['data']['data']->n_registros);self::assertSame([],Estado::$tipos[1]);self::assertNotContains('precio',Estado::$calls);}
 public function testPrecioCambiaDespuesLecturaConservaFilasObservadas():void {Estado::$tipos[1]=[$this->type(1,'80')];Estado::$despues=function(string $etapa):void {if($etapa==='tipo')Estado::$tipos[1]=[['com_producto_id'=>1,'com_conf_precio_precio'=>'90']];};$r=$this->model()->precios_para_alta($this->products(),1);self::assertFalse(errores::$error);self::assertSame(80.0,$r[7]['com_producto_precio']);self::assertSame('90',Estado::$tipos[1][0]['com_conf_precio_precio']);}

 public function testAlcanceSoloFacturaYPartidaExactas():void {
  require_once RAIZ_REPOSITORIO_PRUEBAS.'/controllers/_base_system_fc.php';require_once __DIR__.'/controladores_catalogo.php';
  $ns=implode(chr(92),['gamboamartin','facturacion','controllers','']);
  foreach([['controlador_fc_factura','controlador_fc_partida',true],['controlador_fc_nota_credito','controlador_fc_partida_nc',false],['controlador_fc_complemento_pago','controlador_fc_partida_cp',false],['controlador_fc_nota_credito','controlador_fc_partida',false],['controlador_fc_factura','controlador_fc_partida_nc',false],['FacturaPersonalizada','controlador_fc_partida',false],['controlador_fc_factura','PartidaPersonalizada',false]] as [$ctl,$part,$expected]){
   $r=new ReflectionClass($ns.$ctl);$obj=$r->newInstanceWithoutConstructor();$property=new ReflectionProperty($ns.'_base_system_fc','ctl_partida');$property->setValue($obj,new ($ns.$part));$method=new ReflectionMethod($ns.'_base_system_fc','usa_catalogo_precios_factura');self::assertSame($expected,$method->invoke($obj),$ctl.'/'.$part);
  }
 }
 public function testBaseNoNumericaSeRechazaInclusoConOverride():void {$p=$this->products();$p[7]['com_producto_precio']='NO_NUMERICO';Estado::$precios[1]=[$this->special(1,'70')];$this->expectException(TypeError::class);$this->model()->precios_para_alta($p,1);}
 public function testPrecioTipoNoNumericoNoSeConvierteEnCero():void {Estado::$tipos[1]=[$this->type(1,'NO_NUMERICO')];$this->expectException(TypeError::class);$this->model()->precios_para_alta($this->products(),1);}
 public function testPrecioClienteNoNumericoNoSeConvierteEnCero():void {Estado::$precios[1]=[$this->special(1,'NO_NUMERICO')];$this->expectException(TypeError::class);$this->model()->precios_para_alta($this->products(),1);}

 public function testAcotaAmbasConsultasPorIdsSinStatus():void {$p=$this->products();$p[10]=$p[7];$this->model()->precios_para_alta($p,1);$calls=array_values(array_filter(Estado::$calls,fn($v)=>is_array($v)&&$v[0]==='in_catalogo'));self::assertSame([['in_catalogo',['llave'=>'com_producto.id','values'=>[1,2]]],['in_catalogo',['llave'=>'com_producto.id','values'=>[1,2]]]],$calls);}
 public function testMilesDeOverridesAjenosNoAfectanResultado():void {for($i=0;$i<3000;$i++){Estado::$tipos[1][]=$this->type(99,'1');Estado::$precios[1][]=$this->special(99,'2');}Estado::$tipos[1][]=$this->type(2,'40');Estado::$precios[1][]=$this->special(1,'70',12);$r=$this->model()->precios_para_alta($this->products(),1);self::assertFalse(errores::$error);self::assertSame(70.0,$r[7]['com_producto_precio']);self::assertSame(40.0,$r[9]['com_producto_precio']);self::assertSame(12,$r[7]['cat_sat_conf_imps_id']);}
}
